export const Schema = z
    .object({
    玩家信息: z
        .object({
        姓名: z.string().prefault(''),
        性别: z.string().prefault(''),
        年龄: z
            .preprocess(value => (typeof value === 'string' ? Number.parseFloat(value) : value), z.coerce.number())
            .transform(value => _.clamp(Math.round(value), 0, 120))
            .prefault(0),
        身份: z.string().prefault('待说明'),
        与刘庄的关系: z.string().prefault('待说明'),
        当前状态: z.string().prefault('刚抵达刘庄，尚未安顿'),
        现金: z.coerce
            .number()
            .transform(value => Math.max(0, Number(value.toFixed(2))))
            .prefault(0),
        基础属性: z
            .record(z.enum(['体魄', '灵巧', '思维', '感知', '意志', '亲和']), z.coerce.number().transform(value => _.clamp(Math.round(value), 1, 10)))
            .prefault({ 体魄: 5, 灵巧: 5, 思维: 5, 感知: 5, 意志: 5, 亲和: 5 }),
        技能: z
            .record(z.string().describe('动态技能名称'), z
            .object({
            分类: z.string().prefault('生活'),
            品质: z.enum(['普通', '优秀', '稀有', '史诗', '传说']).prefault('普通'),
            等级: z.coerce
                .number()
                .transform(value => _.clamp(Math.round(value), 0, 10))
                .prefault(0),
            熟练度: z.coerce
                .number()
                .transform(value => Math.max(0, Math.round(value)))
                .prefault(0),
            关联属性: z.string().prefault(''),
            效果: z.string().prefault(''),
        })
            .transform(data => {
            if (data.等级 >= 10) {
                return { ...data, 等级: 10, 熟练度: _.clamp(data.熟练度, 0, 99) };
            }
            const level_gain = Math.floor(data.熟练度 / 100);
            const unclamped_level = data.等级 + level_gain;
            const 等级 = _.clamp(unclamped_level, 0, 10);
            const 熟练度 = 等级 >= 10 && unclamped_level > 10 ? 99 : data.熟练度 % 100;
            return { ...data, 等级, 熟练度 };
        })
            .prefault({}))
            .prefault({}),
        特长: z.record(z.string().describe('特长名称'), z.string()).prefault({}),
        装备: z
            .record(z.string().describe('装备栏位'), z
            .object({
            名称: z.string().prefault(''),
            分类: z.string().prefault(''),
            品质: z.enum(['普通', '优秀', '稀有', '史诗', '传说']).prefault('普通'),
            效果: z.string().prefault(''),
        })
            .prefault({}))
            .prefault({}),
        物品栏: z
            .record(z.string().describe('物品名称'), z
            .object({
            分类: z.string().prefault('杂物'),
            品质: z.enum(['普通', '优秀', '稀有', '史诗', '传说']).prefault('普通'),
            数量: z.coerce
                .number()
                .transform(value => Math.max(0, Math.floor(value)))
                .prefault(1),
            可使用: z.boolean().prefault(false),
            使用后消耗: z.boolean().prefault(false),
            效果: z.string().prefault(''),
            来源: z.string().prefault(''),
        })
            .prefault({}))
            .transform(data => _.pickBy(data, ({ 数量 }) => 数量 > 0))
            .prefault({}),
        人情账: z
            .record(z.string().describe('往来标识'), z
            .object({
            对象: z.string().prefault(''),
            内容: z.string().prefault(''),
            方向: z.enum(['玩家承情', '对方承情', '彼此相抵']).prefault('彼此相抵'),
            状态: z.enum(['未了', '已还', '不再计较']).prefault('未了'),
        })
            .prefault({}))
            .prefault({}),
    })
        .prefault({}),
    世界信息: z
        .object({
        日期时间: z
            .object({
            年: z.coerce
                .number()
                .transform(value => Math.max(1, Math.round(value)))
                .prefault(2001),
            月: z.coerce
                .number()
                .transform(value => Math.round(value))
                .prefault(7),
            日: z.coerce
                .number()
                .transform(value => Math.round(value))
                .prefault(16),
            时: z.coerce
                .number()
                .transform(value => Math.round(value))
                .prefault(7),
            分: z.coerce
                .number()
                .transform(value => Math.round(value))
                .prefault(10),
        })
            .transform(value => {
            const date = new Date(0);
            date.setUTCFullYear(value.年, value.月 - 1, value.日);
            date.setUTCHours(value.时, value.分, 0, 0);
            return {
                年: date.getUTCFullYear(),
                月: date.getUTCMonth() + 1,
                日: date.getUTCDate(),
                时: date.getUTCHours(),
                分: date.getUTCMinutes(),
            };
        })
            .prefault({}),
        星期: z.string().prefault('星期一'),
        时段: z.enum(['清晨', '上午', '正午', '下午', '傍晚', '夜间', '深夜']).prefault('清晨'),
        天气: z.string().prefault('晴热，晨风微弱'),
        农时: z.string().prefault('伏前夏管'),
        玩家当前地点: z.string().prefault('刘庄村口大槐树下'),
        行情: z.record(z.string().describe('商品或劳务'), z.string()).prefault({}),
    })
        .transform(data => {
        const date = new Date(0);
        date.setUTCFullYear(data.日期时间.年, data.日期时间.月 - 1, data.日期时间.日);
        const 星期 = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'][date.getUTCDay()];
        const hour = data.日期时间.时;
        const 时段 = hour < 5
            ? '深夜'
            : hour < 8
                ? '清晨'
                : hour < 11
                    ? '上午'
                    : hour < 14
                        ? '正午'
                        : hour < 18
                            ? '下午'
                            : hour < 20
                                ? '傍晚'
                                : hour < 24
                                    ? '夜间'
                                    : '深夜';
        return { ...data, 星期, 时段 };
    })
        .prefault({}),
    村庄状态: z
        .object({
        发展领域: z
            .record(z.string().describe('动态发展领域'), z
            .object({
            阶段: z.string().prefault('萌芽'),
            现状: z.string().prefault(''),
            成果: z.string().prefault(''),
            问题: z.string().prefault(''),
        })
            .prefault({}))
            .prefault({}),
        项目: z
            .record(z.string().describe('动态项目名称'), z
            .object({
            标签: z.string().prefault(''),
            状态: z.enum(['设想', '调查', '筹备', '推进', '受阻', '完成', '搁置']).prefault('设想'),
            进度: z.coerce
                .number()
                .transform(value => _.clamp(Math.round(value), 0, 100))
                .prefault(0),
            目标: z.string().prefault(''),
            需求: z.string().prefault(''),
            下一步: z.string().prefault(''),
        })
            .prefault({}))
            .prefault({}),
        设施: z
            .record(z.string().describe('设施名称'), z
            .object({
            等级: z.coerce
                .number()
                .transform(value => _.clamp(Math.round(value), 0, 10))
                .prefault(0),
            状态: z.string().prefault(''),
            功能: z.string().prefault(''),
        })
            .prefault({}))
            .prefault({}),
        村内风向: z.string().prefault('多数人正在观望新政策会怎样落到自家日子上'),
    })
        .prefault({}),
    人物档案: z
        .record(z.string().describe('人物数字ID'), z
        .preprocess(value => {
        if (!_.isPlainObject(value))
            return value;
        const normalized = { ...value };
        Object.keys(normalized).forEach(key => {
            const match = key.match(/^(熟悉度|信任度|好感度)\s*[:：]\s*(-?\d+(?:\.\d+)?)\s*$/);
            if (!match)
                return;
            const [, field, number] = match;
            if (!(field in normalized))
                normalized[field] = Number(number);
            delete normalized[key];
        });
        return normalized;
    }, z.object({
        姓名: z.string().prefault('未命名'),
        性别: z.string().prefault(''),
        年龄: z
            .preprocess(value => (typeof value === 'string' ? Number.parseFloat(value) : value), z.coerce.number())
            .transform(value => _.clamp(Math.round(value), 0, 120))
            .prefault(0),
        身份: z.string().prefault(''),
        简短外貌: z.string().prefault(''),
        性格: z.string().prefault(''),
        家庭概况: z.string().prefault(''),
        擅长: z.string().prefault(''),
        当前目标: z.string().prefault(''),
        当前想法: z.string().prefault(''),
        当前状态: z.string().prefault(''),
        所在位置: z.string().prefault(''),
        熟悉度: z
            .union([z.coerce.number().transform(value => _.clamp(Math.round(value), 0, 100)), z.literal('待评估')])
            .prefault('待评估'),
        信任度: z
            .union([
            z.coerce.number().transform(value => _.clamp(Math.round(value), -100, 100)),
            z.literal('待评估'),
        ])
            .prefault('待评估'),
        好感度: z
            .union([
            z.coerce.number().transform(value => _.clamp(Math.round(value), -100, 100)),
            z.literal('待评估'),
        ])
            .prefault('待评估'),
        对玩家态度: z.string().prefault('待评估'),
        经历摘要: z.string().prefault(''),
    }))
        .prefault({}))
        .prefault({}),
    人物关系: z
        .record(z.string().describe('稳定关系标识，推荐使用较小人物ID-较大人物ID'), z
        .object({
        人物: z.string().prefault(''),
        关系: z.string().prefault(''),
        状态: z.string().prefault(''),
        最近变化: z.string().prefault(''),
    })
        .prefault({}))
        .prefault({}),
    系统商店: z
        .object({
        _刷新请求: z.boolean().prefault(false),
        刷新费用: z.coerce
            .number()
            .transform(value => Math.max(0, Number(value.toFixed(2))))
            .prefault(100),
        最近交易: z.string().prefault(''),
        商品: z
            .record(z.string().describe('商品名称'), z
            .object({
            分类: z.string().prefault('杂物'),
            品质: z.enum(['普通', '优秀', '稀有', '史诗', '传说']).prefault('普通'),
            价格: z.coerce
                .number()
                .transform(value => Math.max(0, Number(value.toFixed(2))))
                .prefault(0),
            库存: z.coerce
                .number()
                .transform(value => Math.max(0, Math.floor(value)))
                .prefault(0),
            可使用: z.boolean().prefault(false),
            使用后消耗: z.boolean().prefault(false),
            效果: z.string().prefault(''),
            说明: z.string().prefault(''),
        })
            .prefault({}))
            .prefault({}),
    })
        .prefault({}),
    来往事项: z
        .record(z.string().describe('事项标识'), z
        .object({
        类型: z.string().prefault('日常'),
        内容: z.string().prefault(''),
        状态: z.enum(['待回应', '进行中', '已办妥', '已搁置', '已失约']).prefault('待回应'),
        相关人物: z.string().prefault(''),
        下一步: z.string().prefault(''),
    })
        .prefault({}))
        .prefault({}),
    信息与传闻: z
        .record(z.string().describe('信息标识'), z
        .object({
        内容: z.string().prefault(''),
        来源: z.string().prefault(''),
        状态: z.enum(['未核实', '部分属实', '已证实', '已证伪']).prefault('未核实'),
    })
        .prefault({}))
        .prefault({}),
    长期记录: z
        .object({
        阶段总结: z.string().prefault(''),
        近期记录: z.record(z.string().describe('日期或事件标识'), z.string()).prefault({}),
    })
        .prefault({}),
    系统状态: z
        .object({
        初始化状态: z.enum(['等待玩家说明', '进行中', '完成']).prefault('等待玩家说明'),
    })
        .prefault({}),
})
    .prefault({});
